// DispatchBacklog runs the :one query against postgresql.
func (q *postgresqlQueries) DispatchBacklog(ctx context.Context, db DBTX) (DispatchBacklogRow, error) {
	row := db.QueryRowContext(ctx, q.dispatchBacklog)

	var i DispatchBacklogRow

	err := row.Scan(
		&i.Depth,
		&i.Oldest,
	)

	return i, err
}

// FetchClaimedDispatches runs the :many query against postgresql.
func (q *postgresqlQueries) FetchClaimedDispatches(ctx context.Context, db DBTX, arg FetchClaimedDispatchesParams) ([]FetchClaimedDispatchesRow, error) {
	rows, err := db.QueryContext(ctx, q.fetchClaimedDispatches,
		arg.IDs,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []FetchClaimedDispatchesRow

	for rows.Next() {
		var i FetchClaimedDispatchesRow

		if err := rows.Scan(
			&i.ID,
			&i.DeliveryID,
			&i.OrderingKey,
			&i.Attempts,
			&i.EventType,
			&i.Payload,
			&i.Scope,
			&i.EndpointID,
			&i.EndpointScope,
			&i.EndpointCreatedBy,
			&i.EndpointName,
			&i.EndpointURL,
			&i.EndpointContentType,
			&i.EndpointSecretCurrent,
			&i.EndpointSecretPrevious,
			&i.EndpointHeaders,
			&i.EndpointDisabled,
			&i.EndpointCreatedAt,
			&i.EndpointLastUpdatedAt,
			&i.EndpointArchivedAt,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

